package ru.neverland.townycrime;
import java.util.*;
/** City patrol assignments and confirmed observations. Neither record implies guilt. */
public final class CrimePatrols {
    private CrimePatrols(){}
    public enum Phase { ASSIGNED, COMPLETED, CANCELLED }
    public static String text(String value,int min,int max){if(value==null||value.strip().length()<min||value.length()>max||value.chars().anyMatch(c->Character.isISOControl(c)||c=='§'||c=='&'))throw new IllegalArgumentException("Текст: "+min+"–"+max+" символов, без переносов и кодов цвета");return value.strip();}
    public record Patrol(UUID id,UUID town,String district,String districtName,UUID worker,String workerName,UUID issuer,long created,Phase phase,String report,UUID author,long closed,long revision){
        public Patrol{Objects.requireNonNull(id);Objects.requireNonNull(town);Objects.requireNonNull(worker);Objects.requireNonNull(issuer);Objects.requireNonNull(phase);if(district==null||!district.matches("[a-z0-9_-]{1,32}"))throw new IllegalArgumentException("Неверный район");districtName=text(districtName,1,48);workerName=text(workerName,1,64);Objects.requireNonNull(report);if(created<0||revision<1||closed<0||phase==Phase.ASSIGNED&&(!report.isEmpty()||author!=null||closed!=0)||phase!=Phase.ASSIGNED&&(author==null||closed<created))throw new IllegalArgumentException("Неверный патруль");if(phase!=Phase.ASSIGNED)report=text(report,5,300);}
        public Patrol finish(Phase next,UUID by,String message,long now){if(phase!=Phase.ASSIGNED||next==Phase.ASSIGNED)throw new IllegalArgumentException("Патруль уже закрыт");return new Patrol(id,town,district,districtName,worker,workerName,issuer,created,next,message,by,now,Math.incrementExact(revision));}
    }
    public record Incident(UUID id,UUID town,String kind,String resource,long amount,long created){
        public Incident{Objects.requireNonNull(id);Objects.requireNonNull(town);if(created<0||!Set.of("BURGLARY","EXTORTION").contains(kind)||resource==null||amount<0||amount>1_000_000_000L||kind.equals("BURGLARY")&&(!CrimeSettings.RESOURCE_IDS.contains(resource)||amount<1)||kind.equals("EXTORTION")&&(!resource.isEmpty()||amount!=0))throw new IllegalArgumentException("Неверное происшествие");}
        public static Optional<Incident> confirmed(CrimeState state){var i=state.incident();return i==null||!Set.of("APPLIED","CLOSED").contains(i.phase())?Optional.empty():Optional.of(new Incident(i.id(),state.town(),i.kind(),i.resource(),i.amount(),i.created()));}
        public Map<String,Object> evidence(){return Map.of("sourceId","crime:"+id,"id",id.toString(),"town",town.toString(),"kind",kind,"resource",resource,"amount",amount,"created",created,"phase","APPLIED","scope","CITY","amountUnit","THOUSANDTH_RESOURCE");}
    }
    public record State(Map<UUID,Patrol> patrols,Map<UUID,Incident> incidents,long revision){
        public State{patrols=Map.copyOf(patrols);incidents=Map.copyOf(incidents);if(revision<0||patrols.size()>10_000||incidents.size()>20_000)throw new IllegalArgumentException("Журнал патрулей заполнен; требуется архивирование");var active=new HashSet<String>();var counts=new HashMap<UUID,Integer>();for(var e:patrols.entrySet()){var p=e.getValue();if(p.phase()==Phase.ASSIGNED&&counts.merge(p.town(),1,Integer::sum)>256)throw new IllegalArgumentException("Не более 256 действующих патрулей города");if(!e.getKey().equals(p.id())||p.phase()==Phase.ASSIGNED&&!active.add(p.town()+"/"+p.worker()))throw new IllegalArgumentException("У жителя уже есть действующий патруль");}for(var e:incidents.entrySet())if(!e.getKey().equals(e.getValue().id()))throw new IllegalArgumentException("Неверный ID происшествия");}
        public static State empty(){return new State(Map.of(),Map.of(),0);}
        public State patrol(Patrol value){var next=new HashMap<>(patrols);var old=next.get(value.id());if(old==null){if(value.revision()!=1||value.phase()!=Phase.ASSIGNED)throw new IllegalArgumentException("Новый патруль должен быть назначен");}else if(!old.id().equals(value.id())||!old.town().equals(value.town())||!old.district().equals(value.district())||!old.districtName().equals(value.districtName())||!old.worker().equals(value.worker())||!old.workerName().equals(value.workerName())||!old.issuer().equals(value.issuer())||old.created()!=value.created()||old.phase()!=Phase.ASSIGNED||value.phase()==Phase.ASSIGNED||value.revision()!=old.revision()+1)throw new IllegalArgumentException("Назначение изменилось; откройте меню снова");next.put(value.id(),value);return new State(next,incidents,Math.incrementExact(revision));}
        public State observe(Collection<Incident> values){var next=new HashMap<>(incidents);for(var value:values){var old=next.putIfAbsent(value.id(),value);if(old!=null&&!old.equals(value))throw new IllegalArgumentException("Происшествие с этим ID уже имеет другие сведения");}return next.equals(incidents)?this:new State(patrols,next,Math.incrementExact(revision));}
    }
}
